# --- Example usage ---------------------------------------------------
# use lib '.';      # or wherever GeologicalNeighbors.pm lives
# use GeologicalNeighbors qw(%neighbor);
# if ($neighbor{FR}{DE}) { print "France and Germany share a border\n"; }
